enum Event {
    Key(char),
    Click { x: i32, y: i32 },
    Quit,
}

fn describe(event: &Event) -> String {
    match event {
        Event::Key(c) => format!("key {c}"),
        Event::Click { x, y } if *x >= 0 && *y >= 0 => format!("click at {x},{y}"),
        Event::Quit => "quit".to_string(),
    }
}

fn main() {
    println!("{}", describe(&Event::Quit));
}

